// Быстрый поиск с доступом к каждому тесту, включая последние добавления.
function hub(subject){const host=document.getElementById(subject);if(!host||host.querySelector('.audit-search'))return;const panel=document.createElement('section');panel.className='section audit-search';const h=extraNode('h2','Найти тест');const input=extraNode('input');input.type='search';input.className='triangle-input';input.placeholder='Тема, класс или название теста';input.setAttribute('aria-label','Поиск тестов');const results=document.createElement('div');results.className='audit-search-results';const counter=extraNode('p');counter.setAttribute('aria-live','polite');panel.append(h,input,counter,results);host.prepend(panel);
const topics=subjectCatalog[subject].topics.filter(t=>t.extra!==undefined);const unique=[...new Map(topics.map(t=>[t.extra,t])).values()];
function search(){const term=input.value.toLocaleLowerCase('ru').trim();const found=unique.filter(t=>(t.name+' '+extraTests[t.extra].title+' '+t.grades.join(' ')).toLocaleLowerCase('ru').includes(term));counter.textContent='Найдено тестов: '+found.length;results.replaceChildren();for(const t of found){const card=extraNode('div',undefined,'audit-search-item');const title=extraNode('strong',extraTests[t.extra].title);const meta=extraNode('span',t.grades.join(', ')+' класс · 15 вопросов · 5 открытых');const b=extraNode('button','Открыть','button');b.onclick=()=>{catalogSelection={subject,grade:t.grades[0],topic:t};openExtra(t.extra);addTestBreadcrumb();};card.append(title,meta,b);results.append(card);}}input.addEventListener('input',search);search();}
const renderBeforeAudit=renderCatalog;renderCatalog=function(subject,grade,topic){renderBeforeAudit.apply(this,arguments);if(!grade&&!topic)hub(subject);};
const examBeforeAudit=renderExam;renderExam=function(subject,exam){examBeforeAudit.apply(this,arguments);document.querySelectorAll('[data-ege-first12]').forEach(card=>{card.querySelector('h3').textContent='ЕГЭ · Сборник: 15 заданий';card.querySelector('p').textContent='Теория и объяснения, 10 заданий с выбором и 5 открытых, рисунки и графики.';});};
const start=document.getElementById('home');if(start){const block=document.createElement('section');block.className='section audit-start';block.innerHTML='<h2>Продолжить обучение</h2><p>Выберите предмет или откройте последние подборки.</p>';for(const s of ['math','physics']){const b=extraNode('button',subjectCatalog[s].title,'button');b.onclick=()=>renderCatalog(s);block.append(b);}for(const [title,hash] of [['ЕГЭ: повторение','#ege-repeat-models'],['Отрицательные степени','#negative-powers']]){const a=extraNode('a',title,'button');a.href=hash;block.append(a);}start.prepend(block);}
